<?php

declare(strict_types=1);
if (basename((string)($_SERVER['SCRIPT_FILENAME'] ?? '')) === basename(__FILE__)) { http_response_code(403); exit; }

function teacher_ops_pct(mixed $value,int $dec=0): string { return $value===null||$value===''?'—':number_format((float)$value,$dec,',',' ').' %'; }
function teacher_ops_delta(mixed $value,bool $inverse=false): string
{
    if($value===null||$value==='')return '—';$v=(float)$value;$good=$inverse?$v<0:$v>0;$class=abs($v)<.05?'neutral':($good?'good':'bad');return '<span class="ops-delta '.$class.'">'.($v>0?'+':'').number_format($v,1,',',' ').'</span>';
}
function teacher_ops_student_url(string $classId,string $studentKey): string { return 'teacher.php?'.http_build_query(['tab'=>'student360','class'=>$classId,'student'=>$studentKey]); }

