    <section class="ops-kpis"><article><span>Projektový průměr</span><strong><?=teacher_ops_pct($snapshot['avg_project_pct']??null)?></strong></article><article><span>Mastery</span><strong><?=teacher_ops_pct($snapshot['avg_mastery']??null)?></strong></article><article><span>Úkoly hotovo</span><strong><?=$data['task_stats']['total']?round($data['task_stats']['done']/$data['task_stats']['total']*100):0?> %</strong><small><?=$data['task_stats']['overdue']?> po termínu</small></article><article><span>Retry efekt</span><strong><?=teacher_ops_delta($data['retry']['delta']??null)?></strong><small>poslední vs první pokus</small></article></section>
    <div class="ops-analytics-grid"><section class="teacher-panel ops-chart-panel"><div class="teacher-panel-head"><div><span>8 týdnů</span><h2>Výkon a aktivita</h2></div></div><div class="ops-trend-chart"><?php foreach($data['weeks'] as $week): ?><div><span><?=e((string)$week['label'])?></span><i style="--project:<?=e((string)($week['project_avg']??0))?>%;--test:<?=e((string)($week['test_avg']??0))?>%"><b title="Projekt <?=teacher_ops_pct($week['project_avg']??null)?>"></b><em title="Test <?=teacher_ops_pct($week['test_avg']??null)?>"></em></i><small><?= (int)$week['labs'] ?> lab</small></div><?php endforeach; ?></div></section><section class="teacher-panel"><div class="teacher-panel-head"><div><span>Skill mastery</span><h2>Nejslabší větve</h2></div></div><div class="ops-branch-list"><?php foreach($data['branch_averages'] as $slug=>$value): ?><div><span><?=e((string)$slug)?></span><progress max="100" value="<?=e((string)$value)?>"></progress><b><?=teacher_ops_pct($value)?></b></div><?php endforeach; ?></div></section></div>
    <section class="teacher-panel"><div class="teacher-panel-head"><div><span>Heatmapa</span><h2>Student × skill větev</h2><p>Čím nižší hodnota, tím větší prostor pro cílený zásah.</p></div></div><?php $branches=array_keys((array)$data['branch_averages']); ?><div class="ops-heatmap"><div class="ops-heat-head"><span>Student</span><?php foreach($branches as $branch): ?><b><?=e((string)$branch)?></b><?php endforeach; ?></div><?php foreach($data['heatmap'] as $row): ?><div class="ops-heat-row"><span><?=e((string)$row['label'])?></span><?php foreach($branches as $branch): $v=(float)($row['cells'][$branch]??0); ?><i style="--v:<?=$v?>" title="<?=e((string)$branch)?> · <?=teacher_ops_pct($v)?>"><?=$v?round($v):'—'?></i><?php endforeach; ?></div><?php endforeach; ?></div></section>
    <section class="teacher-panel"><div class="teacher-panel-head"><div><span>Lesson Intelligence</span><h2>Lekce podle tření</h2><p>Friction kombinuje predikce, mentální model, teach-back a připravenost simulace. Slouží k prioritizaci, ne k automatickému hodnocení.</p></div></div><div class="ops-lesson-intel"><?php foreach(array_slice($lessons,0,14) as $lesson): ?><article><div class="ops-friction"><strong><?=number_format((float)$lesson['friction'],0)?></strong><span>friction</span></div><div><span>L<?=str_pad((string)$lesson['lesson_number'],2,'0',STR_PAD_LEFT)?></span><h3><?=e((string)$lesson['title'])?></h3><p><?=e((string)$lesson['suggestion'])?></p><small>Predikce <?=teacher_ops_pct($lesson['prediction_accuracy'])?> · model <?=teacher_ops_pct($lesson['model_accuracy'])?> · explain <?=teacher_ops_pct($lesson['teachback_rate'])?> · sim ready <?=teacher_ops_pct($lesson['simulation_ready'])?></small></div><a href="?tab=teach&class=<?=e($classId)?>&lesson=<?=$lesson['lesson_number']?>">Otevřít lekci →</a></article><?php endforeach; ?></div></section>
    <?php
}

function teacher_render_command_palette(): void
{
    $entries=teacher_ops_command_entries();?><div class="ops-command-backdrop" data-command-backdrop hidden><div class="ops-command" role="dialog" aria-modal="true" aria-label="Rychlé hledání"><header><span>⌘K</span><input type="search" placeholder="Student, třída, stránka nebo akce…" data-command-input autocomplete="off"><button type="button" data-command-close>Esc</button></header><div class="ops-command-results" data-command-results><?php foreach($entries as $entry): ?><a href="<?=e((string)$entry['url'])?>" data-command-item data-search="<?=e(normalized_person_name((string)$entry['label'].' '.(string)$entry['hint'].' '.(string)$entry['keywords']))?>"><strong><?=e((string)$entry['label'])?></strong><small><?=e((string)$entry['hint'])?></small></a><?php endforeach; ?></div><footer><span>↑↓ pohyb</span><span>Enter otevřít</span><span>Esc zavřít</span></footer></div></div><?php
}

function teacher_render_team_admin(): void
{
    $members=teacher_ops_team_members();$can=teacher_permission('roles.manage');$current=teacher_role();
    ?><section class="teacher-page-head"><div><div class="eyebrow">Team access</div><h1>Učitelský tým a role</h1><p><?=e(teacher_team_label())?> · role jsou ověřované serverem a vázané na konkrétní teacher actor.</p></div><span class="ops-role-badge"><?=e(teacher_role_label())?></span></section>
    <section class="teacher-panel"><div class="teacher-panel-head"><div><span>Členové</span><h2><?=count($members)?> známých učitelských actorů</h2><p>Člen se do registru zapíše při úspěšném přihlášení. Lead může měnit pouze Učitel ↔ Asistent; Admin může spravovat všechny role.</p></div></div><div class="ops-filter-manager"><?php foreach($members as $member): $role=(string)($member['role']??'teacher'); ?><article><div><span><?=e(teacher_role_label($role))?></span><strong><?=e((string)($member['label']??'Učitel'))?></strong><small>Naposledy <?=!empty($member['last_seen_at'])?e(date('d.m.Y H:i',strtotime((string)$member['last_seen_at']))):'—'?></small></div><b><?=hash_equals((string)($member['owner_key']??''),teacher_saved_filter_owner_key())?'Ty':'Člen'?></b><?php if($can&&($current==='admin'||!in_array($role,['admin','lead'],true))): ?><form method="post" class="ops-role-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="teacher_team_member_role"><input type="hidden" name="member_owner_key" value="<?=e((string)$member['owner_key'])?>"><select name="member_role" onchange="this.form.submit()" aria-label="Role <?=e((string)($member['label']??''))?>"><?php $roles=$current==='admin'?['admin','lead','teacher','assistant']:['teacher','assistant']; foreach($roles as $r): ?><option value="<?=e($r)?>" <?=$r===$role?'selected':''?>><?=e(teacher_role_label($r))?></option><?php endforeach; ?></select></form><?php else: ?><span>read-only</span><?php endif; ?></article><?php endforeach; ?><?php if(!$members): ?><div class="teacher-empty">Zatím není evidován žádný člen týmu.</div><?php endif; ?></div></section><?php
}
